"""Publish the actual two-hand phrase encounter and scoped Godot evidence."""
from pathlib import Path
import hashlib, html, json, shutil
ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'doc/book/iterations/2026-10-11-teach-a-sphere-phrase'
RUN = ROOT / 'ada_run/encounter_pilot/ML_Perception/movement_learning'
ART = ROOT / 'commons/artifacts/vogue_timeline'

def main():
    tests = json.loads((OUT / 'tests.json').read_text(encoding='utf-8'))
    museum = json.loads((RUN / 'report.json').read_text(encoding='utf-8'))
    assert tests['passed'] and museum['passed']
    previous = 0
    for folder, name in [('2026-10-11-teach-a-sphere', 'pose'), ('2026-10-11-teach-a-sphere-height', 'height'), ('2026-10-11-vogue-a-phrase-of-your-own', 'dance')]:
        source = ROOT / 'doc/book/iterations' / folder / 'tests.json'
        data = json.loads(source.read_text(encoding='utf-8'))
        assert not data['failures']
        previous += len(data['checks'])
        shutil.copy2(source, OUT / f'{name}-tests.json')
    log = (RUN / 'stdout.log').read_text(encoding='utf-8', errors='replace')
    assert 'SCRIPT ERROR:' not in log
    for name in ['museum', 'empty', 'phrase-1', 'phrase-3', 'reversed']:
        shutil.copy2(RUN / f'{name}.png', OUT / f'{name}.png')
    shutil.copy2(RUN / 'report.json', OUT / 'museum-tests.json')
    shutil.copy2(ART / 'PHRASE.md', OUT / 'notes.md')
    for name in ['movement_learner.gd', 'movement_learning.gd', 'pose_learning_station.gd']:
        shutil.copy2(ART / name, OUT / name)
    diagnostics = [s for s in log.splitlines() if s.startswith(('ERROR:', 'WARNING:', 'SCRIPT ERROR:'))]
    (OUT / 'museum-diagnostics.json').write_text(json.dumps(diagnostics, indent=2), encoding='utf-8')
    count, spatial = len(tests['checks']), len(museum['checks'])
    e = tests['evidence']
    matched = e['heldout']['fresh_match']['rms']
    reversed_error = e['heldout']['reversed']['rms']
    code = html.escape((ART / 'movement_learner.gd').read_text(encoding='utf-8'))
    content = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The sphere keeps a phrase · Endless Museum</title><style>
    :root{{color-scheme:dark}}*{{box-sizing:border-box}}body{{margin:0;background:#11131d;color:#f4f1f6;font:18px/1.65 system-ui,sans-serif}}main{{max-width:1200px;margin:auto;padding:48px 26px 90px}}h1{{font-size:clamp(40px,7vw,84px);line-height:1.08;letter-spacing:-.05em;max-width:1000px}}h2{{margin-top:2.2em}}a{{color:#7dd6ff}}.lead{{font-size:24px;max-width:900px}}.kicker{{color:#ffc567;letter-spacing:.1em;text-transform:uppercase;font-size:13px}}figure{{margin:30px 0}}img{{display:block;width:100%;border-radius:8px;aspect-ratio:3/2}}figcaption{{font-size:14px;color:#c0bfd0;margin-top:10px}}.grid{{display:grid;grid-template-columns:1fr 1fr;gap:24px}}.card{{padding:24px;background:#1b2031;border:1px solid #373c52;border-radius:10px}}.card h2{{margin-top:0}}table{{border-collapse:collapse;width:100%;font-size:16px}}td,th{{text-align:left;padding:14px;border-bottom:1px solid #3b4158;vertical-align:top}}pre{{font-size:13px;line-height:1.5;overflow:auto;padding:24px;background:#070a12}}.stamp{{display:inline-block;border:1px solid #65727b;padding:8px 14px;border-radius:24px;font-size:14px}}li{{margin:12px 0}}@media(max-width:760px){{.grid{{grid-template-columns:1fr}}main{{padding:26px 16px}}}}</style></head>
    <body><main><p class="kicker">Endless Museum · ML_Perception · 11 October 2026</p><h1>The sphere<br>keeps a phrase.</h1><p class="lead">Two hands, eight beats, one small movement. Teach it through whole performances, then see whether the sphere recognises a new one.</p><p class="stamp">{count} phrase checks · {spatial} museum checks · {previous} carried pose, height and dance checks</p>
    <figure><img src="museum.png" alt="The phrase-learning station beside the existing dance inside the actual museum"><figcaption>Actual Godot museum capture. PHRASE is a third lesson at the existing station. The same sphere remains the responding object.</figcaption></figure>
    <div class="grid"><section class="card"><h2>What carries forward</h2><p>The hand points become traces again. Their positions stay ordered in time. The same sphere now responds to a completed movement, building on its pose and continuous-height lessons.</p><p>POSE, HEIGHT and PHRASE keep separate examples and local saves. Moving between lessons preserves the work.</p></section><section class="card"><h2>What is learned</h2><p>Three or more complete takes produce two average timed paths and per-hand distance limits. A fresh performance is compared at corresponding moments.</p><p>This is a small learned prototype, not a recurrent neural network. It keeps the distinction between left and right, the order of movement and its four-second timing.</p></section></div>
    <h2>Try it in VR</h2><ol><li>Choose <strong>PHRASE → TEACH</strong>. Invent a short movement with both hands: open, lift, sweep forward, return—or your own phrase.</li><li>Press <strong>CAPTURE</strong>. Prepare during the three-second count-in. Move for <strong>eight beats at 120 BPM</strong>. Pink and cyan trails follow both hands through 3D space.</li><li>Record at least <strong>three complete performances</strong>, starting similarly and keeping roughly the same timing. UNDO removes the last teaching take.</li><li>Press <strong>TRAIN</strong>. Inspect the two fitted paths. REPLAY shows the learned phrase with the sphere and moving hand tips.</li><li>In <strong>TEST</strong>, CAPTURE a new performance. Read each hand's error. Then try a reversal or keep one hand still.</li><li>Press <strong>TRY</strong> for another count-in. A recognised phrase makes the sphere replay between its two learned paths. A mismatch leaves it waiting.</li><li><strong>SAVE / LOAD</strong> keeps the phrase locally. SOUND switches the quiet beat click. RESET needs two presses and affects only this lesson.</li></ol>
    <figure><img src="empty.png" alt="The empty phrase station showing capture, train, test, try and replay controls"><figcaption>The station arrives with no taught phrase. Capturing is deliberate; each entire performance becomes one example.</figcaption></figure>
    <h2>Order becomes part of the object</h2><p>The next captures use three labelled synthetic demonstrations fitted inside Godot and a separate synthetic test performance. These are actual renders of the running museum, not illustrations of a proposed feature. They do not establish human recognition accuracy.</p>
    <div class="grid"><figure><img src="phrase-1.png" alt="Two learned hand paths and the original sphere replaying the phrase at one second"><figcaption>One second into the response. The sphere follows the two paths' midpoint; its size follows their separation.</figcaption></figure><figure><img src="phrase-3.png" alt="The same sphere and hand tips at a later moment in the learned phrase"><figcaption>Three seconds into the same phrase. The model retains the path through time, including depth.</figcaption></figure></div>
    <figure><img src="reversed.png" alt="A reversed test performance is rejected while the sphere waits"><figcaption>The tested phrase uses the same kinds of positions in reverse order. It no longer matches. This is not guaranteed for symmetric phrases that resemble their own reversal.</figcaption></figure>
    <h2>What passed</h2><table><thead><tr><th>Test</th><th>Observed result</th></tr></thead><tbody><tr><td>Fresh complete performance</td><td>Matched. Left RMS error {matched[0]*0.65:.3f} m; right {matched[1]*0.65:.3f} m in the synthetic fixture.</td></tr><tr><td>Reverse the order</td><td>Rejected. Left error {reversed_error[0]*0.65:.3f} m; right {reversed_error[1]*0.65:.3f} m.</td></tr><tr><td>Swap hands, hold one still, greatly retime or displace the movement</td><td>All four additional negative fixture variations were withheld.</td></tr><tr><td>Change teaching demonstrations</td><td>The fitted paths change. Their means match an independent calculation within 10⁻⁸ normalised units.</td></tr><tr><td>Fresh testing, save and reload</td><td>Testing leaves the model fixed. Local reload preserves recognition and starts a fresh evaluation record.</td></tr><tr><td>Lost tracking or timing interruption</td><td>The entire unfinished take is discarded. Missing movement is not filled with a stationary hand.</td></tr><tr><td>Carry the object and previous lessons</td><td>The same sphere instance remains across all three lessons. Pose, height and dance regression checks pass.</td></tr></tbody></table>
    <h2>A small, inspectable model</h2><p>Each recorded sample stores a timestamp and six head-relative hand coordinates. The model samples every take at 41 matching instants over four seconds, then averages each coordinate. Recognition checks both hands separately against fitted limits with explicit minimum and maximum bounds.</p><p>There is no time warping, continuous background recognition or generated choreography. The original takes retain their timestamps. Manual REPLAY is labelled a preview; only a successful TRY is a recognition-triggered response.</p><p>Mean-based representatives have a simple precedent in <a href="https://scikit-learn.org/stable/modules/generated/sklearn.neighbors.NearestCentroid.html">centroid classification</a>. This is our own ordered, single-phrase model with rejection policies. <a href="https://dynamictimewarping.github.io/py-api/html/api/dtw.dtw.html">Time warping</a> could later address variable rhythm; it is not part of this version.</p>
    <h2>What averaging leaves out</h2><p>The learned path is not an ideal performance. Averaging can soften an accent or create a trajectory nobody performed. Looking at that result, removing a take and teaching again lets the visitor act on the model's choices.</p><p>Matching measured controller paths does not establish artistic merit or cultural competence. Three takes is a starting requirement, not evidence of broad accuracy. Headset comfort, human timing variation and device performance still need playing.</p>
    <h2>Compact lesson instruction</h2><p class="card">Carry sphere + hand points. Record whole takes; preserve time and left/right. Fit two mean trajectories. Test new performances, reverse order, hold one hand still. Recognised phrase activates the same sphere. Inspect what averaging erases. Never count training frames as fresh tests.</p>
    <h2>Code and evidence</h2><p><a href="notes.md">Full interaction and implementation notes</a> · <a href="movement_learner.gd">Complete phrase model</a> · <a href="movement_learning.gd">Museum interaction</a> · <a href="pose_learning_station.gd">Shared station</a></p><p><a href="tests.json">Phrase tests</a> · <a href="museum-tests.json">Museum tests</a> · <a href="pose-tests.json">Pose</a> · <a href="height-tests.json">Height</a> · <a href="dance-tests.json">Dance</a> · <a href="source-register.json">Source hashes</a></p><p>The surrounding museum retains existing audio-UID, older computer-vision startup and portal diagnostics. They are preserved in the <a href="museum-diagnostics.json">diagnostic record</a>. This artifact's passing checks do not claim a clean whole-project log or a completed Machine Learning tutorial revision.</p><details><summary>Read the complete phrase model</summary><pre><code>{code}</code></pre></details><p><a href="../2026-10-11-teach-a-sphere-height/index.html">Previous: teach the sphere an amount</a></p></main></body></html>'''
    (OUT / 'index.html').write_text(content, encoding='utf-8')
    paths = ['commons/artifacts/vogue_timeline/' + name for name in ['movement_learner.gd', 'movement_learning.gd', 'pose_learning_station.gd', 'height_learning.gd', 'PHRASE.md', 'LEARNING.md', 'HEIGHT.md']]
    paths += ['tools/probes/movement_fixture.gd', 'tools/probes/movement_learning_test.gd', 'tools/probes/movement_learning_museum.gd', 'tools/test_movement_learning.py', 'tools/publish_movement_learning.py']
    (OUT / 'source-register.json').write_text(json.dumps({p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in paths}, indent=2), encoding='utf-8')
    print(f'Published {count} + {spatial} + {previous} passing checks: {OUT}')

if __name__ == '__main__': main()
